Algoritmo Aprobados
  Dimension notas[6] Como Entero;
  Definir aprobados Como Entero <- 0;
  Para i <- 0 Hasta 5 Hacer
    Leer notas[i];
  FinPara
  Para Cada nota En notas Hacer
    Si nota >= 6 Entonces
      aprobados <- aprobados + 1;
    FinSi
  FinPara
  Escribir aprobados;
FinAlgoritmo
